// Third Party
import { useTranslation } from "react-i18next";

// Styles
import styles from "@/Styles/modules/FetchingLoader.module.css";

interface LoaderProps {
  message?: string;
  className?: string;
}

export const FetchingLoader = ({ message, className = "" }: LoaderProps = {}) => {
  const { t } = useTranslation();
  return (
    <div className={`d-flex flex-column align-items-center justify-content-center ${className}`}>
      <div
        className={`spinner-border text-info ${styles["spinner-size"]}`}
        role="status"
      >
        <span className="visually-hidden">{t("Loading…")}</span>
      </div>
      {message && (
        <span>
          {message}
        </span>
      )}
    </div>
  );
};

export default FetchingLoader;
